algorithms.pseudocode:
Algorithm: TROP_SYM_MARGIN(W)
Input: n x n matrix W
Output: (margin, i_min, j_min)

margin <- +inf
for i = 0 to n-1:
    for j = i+1 to n-1:
        slack <- W[i,i] + W[j,j] - 2*W[i,j]
        if slack < margin:
            margin <- slack
            i_min, j_min <- i, j
return (margin, i_min, j_min)

Time: O(n^2), Space: O(1)
